-- Explicações por artigo — Lei de Controle de Produtos Químicos (Lei nº 10.357, de 2001). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estão sujeitos a controle e fiscalização, em todas as etapas (fabricação, armazenamento, compra, venda, posse, transporte, importação, exportação, utilização, entre outras), todos os produtos químicos que possam ser utilizados como insumo na elaboração de substâncias entorpecentes, psicotrópicas ou que determinem dependência física ou psíquica. O controle aplica-se também a essas substâncias quando não estiverem sob controle do Ministério da Saúde. Considera-se produto químico a substância química e as formulações que a contenham, nas concentrações estabelecidas em portaria, em qualquer estado físico, independentemente do nome fantasia e do uso lícito a que se destina.', '["Controle de todos os produtos químicos usados como insumo de drogas.","Abrange todas as etapas, da fabricação à utilização.","Aplica-se a substâncias sem controle do Ministério da Saúde.","Conceito de produto químico por concentração em portaria."]'::jsonb, '["O controle vale mesmo para uso LÍCITO e independe do nome fantasia."]'::jsonb, 'Um solvente usado na indústria também se sujeita ao controle se puder servir de insumo para drogas.', '["Assertiva que dispensa o controle quando o produto tem uso lícito erra."]'::jsonb, '[{"termo":"Insumo","significado":"Produto usado como matéria-prima na fabricação de outro."}]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministro de Estado da Justiça, de ofício ou por proposta do Departamento de Polícia Federal, da Secretaria Nacional Antidrogas ou da Anvisa, definirá, em portaria, os produtos químicos a serem controlados e, quando necessário, promoverá sua atualização, incluindo ou excluindo produtos, bem como estabelecerá os critérios e as formas de controle.', '["Lista de produtos controlados definida por portaria do Ministro da Justiça.","Pode agir de ofício ou por proposta da PF, da Secretaria Nacional Antidrogas ou da Anvisa.","Atualização para incluir ou excluir produtos."]'::jsonb, '["A lista é infralegal (portaria), e não da lei."]'::jsonb, 'Uma portaria inclui novo produto na lista de controlados.', '["Assertiva que fixa a lista de produtos na própria lei erra: ela é por portaria."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Departamento de Polícia Federal o controle e a fiscalização dos produtos químicos a que se refere o art. 1º e a aplicação das sanções administrativas decorrentes.', '["Controle e fiscalização pela Polícia Federal.","Aplicação das sanções administrativas."]'::jsonb, '["Quem fiscaliza produtos químicos controlados é a POLÍCIA FEDERAL (e não o Exército)."]'::jsonb, 'A PF fiscaliza o depósito de produtos químicos controlados.', '["Assertiva que atribui ao Exército a fiscalização dos produtos químicos desta Lei erra: é da Polícia Federal."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para exercer qualquer atividade sujeita a controle e fiscalização, a pessoa física ou jurídica deverá se cadastrar e requerer licença de funcionamento ao Departamento de Polícia Federal, nos termos da portaria do art. 2º, independentemente de outras exigências legais. As pessoas jurídicas já cadastradas providenciarão o recadastramento. Quem exercer a atividade de modo eventual deverá se cadastrar e requerer autorização especial para suas operações.', '["Cadastro e licença de funcionamento na PF.","Recadastramento das já cadastradas.","Atividade eventual: cadastro e autorização especial."]'::jsonb, '["Licença para atividade REGULAR; autorização especial para atividade EVENTUAL."]'::jsonb, 'A empresa que revende solventes controlados exige licença de funcionamento da PF.', '["Assertiva que dispensa o cadastro de quem exerce a atividade apenas eventualmente erra: exige autorização especial."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

