select u.id, u.content_sha256, 'A pessoa jurídica referida no caput do art. 4º deverá requerer, anualmente, a renovação da licença de funcionamento para o prosseguimento de suas atividades.', '["Renovação anual da licença de funcionamento."]'::jsonb, '["Periodicidade ANUAL."]'::jsonb, 'A empresa renova sua licença da PF todo ano.', '["Assertiva que fixa a renovação a cada cinco anos erra: é anual."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
