insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todas as partes envolvidas deverão possuir licença de funcionamento, exceto quando se tratar de quantidades de produtos químicos inferiores aos limites a serem estabelecidos em portaria do Ministro da Justiça.', '["Todas as partes da operação devem ter licença.","Exceção: quantidades inferiores aos limites da portaria."]'::jsonb, '["Vendedor e comprador precisam estar licenciados."]'::jsonb, 'Quem compra de fornecedor sem licença descumpre a Lei, salvo quantidade abaixo do limite.', '["Assertiva que exige licença apenas do vendedor erra: todas as partes devem tê-la."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-6'
