insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa jurídica que realizar qualquer das atividades do art. 1º é obrigada a fornecer ao Departamento de Polícia Federal, periodicamente, informações sobre suas operações. Os documentos que consubstanciam essas informações deverão ser arquivados pelo prazo de cinco anos e apresentados à PF quando solicitados.', '["Informações periódicas à PF.","Arquivo dos documentos por cinco anos."]'::jsonb, '["Guarda por CINCO anos."]'::jsonb, 'A empresa envia à PF mapas periódicos de suas operações e guarda os documentos.', '["Assertiva que fixa em dois anos a guarda dos documentos erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
