insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa física ou jurídica que, por qualquer motivo, suspender o exercício de atividade sujeita a controle e fiscalização ou mudar de atividade controlada deverá comunicar a paralisação ou alteração à Polícia Federal no prazo de trinta dias da suspensão ou mudança.', '["Comunicação de suspensão ou mudança de atividade.","Prazo de trinta dias."]'::jsonb, '["Prazo de TRINTA dias."]'::jsonb, 'A empresa que para de revender o produto controlado avisa a PF em trinta dias.', '["Assertiva que fixa em vinte e quatro horas o prazo para comunicar a suspensão erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-10'
