insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O descumprimento das normas da Lei, independentemente de responsabilidade penal, sujeitará os infratores, cumulativa ou isoladamente, a advertência formal; apreensão do produto químico em situação irregular; suspensão ou cancelamento de licença de funcionamento; revogação da autorização especial; e multa de R$ 2.128,20 a R$ 1.064.100,00. Na dosimetria consideram-se a situação econômica, a conduta, a reincidência, a natureza da infração, a quantidade dos produtos e as circunstâncias. A multa poderá ser paga em até cinco parcelas mensais. Cabe recurso ao Diretor-Geral da Polícia Federal.', '["Medidas: advertência, apreensão, suspensão ou cancelamento de licença, revogação de autorização especial e multa.","Aplicadas cumulativa ou isoladamente.","Multa de R$ 2.128,20 a R$ 1.064.100,00.","Parcelamento da multa em até cinco parcelas.","Recurso ao Diretor-Geral da PF."]'::jsonb, '["As medidas administrativas independem de responsabilidade penal."]'::jsonb, 'Empresa reincidente na omissão de informações recebe multa e suspensão da licença.', '["Assertiva que condiciona as medidas à condenação penal erra: elas independem da esfera penal."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quem cometer qualquer infração terá prazo de trinta dias, a contar da fiscalização, para sanar as irregularidades, sem prejuízo das medidas do art. 14. Sanadas, os produtos apreendidos serão devolvidos ao proprietário. Os produtos não regularizados serão destruídos, alienados ou doados pela PF a instituições de ensino, pesquisa ou saúde pública, após o trânsito em julgado da decisão no processo administrativo. Em caso de risco iminente à saúde pública ou ao meio ambiente, o órgão fiscalizador poderá dar destinação imediata aos produtos apreendidos.', '["Trinta dias para sanar as irregularidades.","Devolução dos produtos após a regularização.","Destruição, alienação ou doação dos não regularizados.","Destinação imediata em caso de risco iminente."]'::jsonb, '["Trinta dias contados da FISCALIZAÇÃO."]'::jsonb, 'A empresa regulariza a licença no prazo e recupera o produto apreendido.', '["Assertiva que fixa em quinze dias o prazo para sanar as irregularidades erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica instituída a Taxa de Controle e Fiscalização de Produtos Químicos, cujo fato gerador é o exercício do poder de polícia conferido ao Departamento de Polícia Federal para controle e fiscalização das atividades do art. 1º.', '["Taxa de Controle e Fiscalização de Produtos Químicos.","Fato gerador: exercício do poder de polícia da PF."]'::jsonb, '["É uma TAXA (tributo), cobrada pelo poder de polícia."]'::jsonb, 'A empresa paga taxa pela fiscalização da PF sobre seus produtos controlados.', '["Assertiva que classifica a cobrança como imposto erra: é taxa."]'::jsonb, '[{"termo":"Poder de polícia","significado":"Atividade estatal que limita direitos em prol do interesse público."}]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São sujeitos passivos da Taxa de Controle e Fiscalização de Produtos Químicos as pessoas físicas e jurídicas que exerçam qualquer das atividades sujeitas a controle e fiscalização de que trata o art. 1º.', '["Sujeito passivo: quem exerce as atividades controladas."]'::jsonb, '["Alcança pessoas físicas e jurídicas."]'::jsonb, 'A distribuidora e o importador pagam a taxa.', '["Assertiva que limita a taxa a pessoas jurídicas erra: inclui as físicas."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-17'
