insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Taxa é devida pela prática dos atos de controle e fiscalização: R$ 500,00 para emissão e alteração do Certificado de Registro Cadastral e para segunda via; R$ 1.000,00 para emissão, segunda via e renovação do Certificado de Licença de Funcionamento; e R$ 50,00 para emissão e segunda via da Autorização Especial. Os valores dos dois primeiros grupos são reduzidos em quarenta por cento para empresa de pequeno porte, cinquenta por cento para filial de empresa já cadastrada e setenta por cento para microempresa.', '["Registro cadastral: R$ 500,00.","Licença de funcionamento: R$ 1.000,00.","Autorização especial: R$ 50,00.","Reduções de quarenta, cinquenta e setenta por cento para empresa de pequeno porte, filial e microempresa."]'::jsonb, '["Reduções não se aplicam à autorização especial (apenas aos grupos I e II)."]'::jsonb, 'A microempresa paga o valor do registro com redução de setenta por cento.', '["Assertiva que aplica as reduções à autorização especial erra: valem só para os grupos I e II."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'quimicos' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

